file.content:
@using Umbraco.Bench.Umbraco.Models.Blocks
@model QuoteModel
<blockquote class="my-6 rounded-r-lg border-l-4 border-amber-500 bg-amber-50 p-6">
    <p class="text-lg italic text-slate-800">“@Model.Quote”</p>
    @if (!string.IsNullOrEmpty(Model.Attribution))
    {
        <footer class="mt-2 text-sm text-slate-600">— @Model.Attribution</footer>
    }
</blockquote>

@using Umbraco.Bench.Umbraco.Models.Blocks
@model ImageModel
<figure class="my-6">
    @if (!string.IsNullOrEmpty(Model.ImageUrl))
    {
        <img src="@Model.ImageUrl" class="w-full rounded-lg border border-slate-200 shadow-sm" alt="@Model.Caption" />
    }
    @if (!string.IsNullOrEmpty(Model.Caption))
    {
        <figcaption class="mt-2 text-center text-sm text-slate-500">@Model.Caption</figcaption>
    }
</figure>

@using Umbraco.Bench.Umbraco.Models.Blocks
@model HeroModel
<section class="relative overflow-hidden bg-slate-900 text-white">
    @if (!string.IsNullOrEmpty(Model.ImageUrl))
    {
        <img src="@Model.ImageUrl" class="absolute inset-0 h-full w-full object-cover opacity-40" alt="" />
    }
    <div class="relative mx-auto max-w-4xl px-6 py-20">
        <h1 class="text-4xl font-bold tracking-tight">@Model.Heading</h1>
        @if (!string.IsNullOrEmpty(Model.Text))
        {
            <p class="mt-4 max-w-2xl text-lg text-slate-300">@Model.Text</p>
        }
    </div>
</section>

tools.description:
Executes template queries and returns generated LINQ code with sample results and execution time.
  IMPORTANT: Always follow the example format exactly.
  Example:
  {"take": 5}
  or
  {
    "documentTypeAlias": "article",
    "filters": [{"propertyAlias": "Name", "constraintValue": "Blog", "operator": "Contains"},
    "take": 10
  }

